// Consommateur : idempotence + budget de retry + DLQ.
export function consume(messages, maxAttempts) {
  // BUG : ni déduplication, ni bonne borne de budget (<= au lieu de <).
  return messages.map((m) => (m.failsBeforeOk <= maxAttempts ? 'applied' : 'dlq'));
}

